import json
from collections import deque, Counter

with open('/tmp/grid_931aad4d.json', 'r') as f:
    task_data = json.load(f)

grid = task_data['grid']
h, w = 12, 24
bg_color = 3

def find_components(grid, bg):
    visited = [[False]*w for _ in range(h)]
    comps = []

    def bfs(color, start):
        comp = [start]
        q = deque([start])
        visited[start[0]][start[1]] = True
        while q:
            r, c = q.popleft()
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = r+dr, c+dc
                if 0 <= nr < h and 0 <= nc < w:
                    if not visited[nr][nc] and grid[nr][nc] == color:
                        visited[nr][nc] = True
                        comp.append((nr, nc))
                        q.append((nr, nc))
        return comp

    unique_colors = sorted(set(c for row in grid for c in row if c != bg))
    for color in unique_colors:
        for r in range(h):
            for c in range(w):
                if grid[r][c] == color and not visited[r][c]:
                    comp = bfs(color, (r,c))
                    if comp:
                        rs = [cell[0] for cell in comp]
                        cs = [cell[1] for cell in comp]
                        bbox_w = max(cs) - min(cs) + 1
                        bbox_h = max(rs) - min(rs) + 1
                        comps.append({
                            'color': color,
                            'size': len(comp),
                            'bbox_h': bbox_h,
                            'bbox_w': bbox_w,
                            'aspect_ratio': bbox_w / bbox_h if bbox_h > 0 else 1
                        })
    return comps

comps = find_components(grid, bg_color)
print(f"Found {len(comps)} components")
for c in sorted(comps, key=lambda x: (-x['size'], x['color'])):
    print(f"Color {c['color']:1d}: size={c['size']:2d}, h={c['bbox_h']}, w={c['bbox_w']}, ratio={c['aspect_ratio']:.2f}")

# Let's try packing components horizontally in order of color
# Each component's shape is preserved exactly
result = [[bg_color]*w for _ in range(h)]

# First, let's extract the exact shape of each component
def get_comp_cells_sorted_by_scan_order(comp_cells):
    """Sort component cells by row then column"""
    return sorted(comp_cells)

comp_shapes = {}
for i, comp in enumerate(comps):
    original_cells = []
    # Need to re-collect actual cells from grid
    for r in range(h):
        for c in range(w):
            if grid[r][c] == comp['color']:
                # Check if this cell belongs to this component (simple check)
                original_cells.append((r, c))
    comp_shapes[comp['color']] = {
        'cells': original_cells,
        'h': max(r for r,c in original_cells),
        'w': max(c for r,c in original_cells)
    }

# Pack all colors together, preserving shapes
# For each color, place its cells in next available positions
current_pos = (0, 0)  # (row_offset, col_offset)
result = [[bg_color]*w for _ in range(h)]

sorted_unique_colors = sorted(Counter([c['color'] for c in comps]).keys())
for color in sorted_unique_colors:
    color_cells = comp_shapes[color]['cells']

    # Find placement position that fits
    found = False
    for start_r in range(h):
        for start_c in range(w):
            # Check if we can fit all these cells starting at (start_r, start_c)
            can_fit = True
            for tr, tc in color_cells:
                nr, nc = start_r + tr, start_c + tc
                if not (0 <= nr < h and 0 <= nc < w):
                    can_fit = False
                    break
            if can_fit:
                # Place it here
                for tr, tc in color_cells:
                    result[start_r + tr][start_c + tc] = color
                found = True
                break
        if found:
            break

print("\nComponents packed (preserve shape, left-to-right by color):")
for row in result[:8]:
    print(' '.join(str(x) for x in row))
print("...")

print(json.dumps({"action": "submit", "grid": result}))
